   right(12) up(27)
     union(){
       pt1 = desc_point(desc,anchor=TOP+BACK+LEFT);
       pt2 = desc_point(desc,anchor=TOP+FWD+RIGHT);
       stroke([pt1,pt2,CENTER], closed=true, width=.5,color="red");

